starter_query:
-- Average salary and total faculty
SELECT ROUND(AVG(salary), 2) AS avg_salary, ...
FROM professors;

-- Experience statistics for doctors
SELECT ...
FROM doctors;

-- Library inventory and unique categories
SELECT SUM(...) AS total_inventory, COUNT(DISTINCT ...) AS distinct_categories
FROM books;

-- Duration range and average rating
SELECT MIN(...) AS min_duration, MAX(...) AS max_duration, ROUND(...) AS avg_rating
FROM movies;

-- Partner restaurants count and average rating
SELECT COUNT(*) AS total_restaurants, ROUND(AVG(rating), 2) AS avg_rating
FROM restaurants;

-- Flight network fare spread
SELECT COUNT(*) AS total_flights, MIN(...) AS min_fare, MAX(...) AS max_fare
FROM flights;

-- Stock units and mean unit cost
SELECT SUM(...) AS total_stock, ROUND(AVG(...), 2) AS avg_unit_cost
FROM stock_items;

-- Stock price range and average
SELECT MAX(...) AS peak_price, MIN(...) AS lowest_price, ROUND(...) AS avg_price
FROM stocks;

-- Job postings volume and average salary ceiling
SELECT COUNT(*) AS total_postings, ROUND(...) AS avg_salary_cap
FROM job_postings;

-- Total posts vs posts containing non-null media
SELECT COUNT(*) AS total_posts, COUNT(...) AS posts_with_media
FROM posts;

-- Total hours and mean rating
SELECT SUM(...) AS total_hours, ROUND(AVG(...), 2) AS avg_rating
FROM assignments;

-- Review volume, distinct products, and average rating
SELECT COUNT(*) AS total_reviews, COUNT(DISTINCT ...) AS reviewed_products, ROUND(...) AS avg_product_rating
FROM reviews;

-- Prescription duration metrics
SELECT ROUND(AVG(duration_days), 1) AS avg_duration_days, MAX(duration_days) AS max_duration_days
FROM prescriptions;

-- Total loans vs completed returns
SELECT COUNT(*) AS total_loans, COUNT(returned_date) AS returned_loans
FROM book_loans;

-- Total ACV and average contract duration
SELECT SUM(...) AS total_acv, ROUND(AVG(...), 1) AS avg_contract_months
FROM contracts;

-- Passenger mileage metrics
SELECT COUNT(*) AS total_passengers, MAX(...) AS max_miles, ROUND(...) AS avg_miles
FROM passengers;

-- Warehouse capacity and unique locations
SELECT SUM(...) AS total_warehouse_capacity, COUNT(DISTINCT ...) AS unique_locations
FROM warehouses;

-- Candidate pool metrics
SELECT COUNT(*) AS total_applicants, ROUND(AVG(...), 2) AS avg_experience, COUNT(...) AS employed_applicants
FROM applicants;

-- User community size and profile bio coverage
SELECT COUNT(*) AS total_users, COUNT(bio) AS users_with_bio
FROM social_users;
